"use client";
import Component from "../smoothui/AiTaskList";
import { useState } from "react";
import { DemoFrame } from "../shared/DemoFrame";
export default function Demo() {
  const [step, setStep] = useState(1);
  const labels = ["Read the brief", "Collect references", "Build the layout", "Check the details"];
  return (
    <DemoFrame>
      <div className="w-full max-w-sm">
        <Component
          label="Design checklist"
          tasks={labels.map((label, index) => ({
            id: String(index),
            label,
            status: index < step ? "done" : index === step ? "running" : "pending",
          }))}
        />
        <button className="demo-action mt-7" onClick={() => setStep(step === 4 ? 0 : step + 1)}>
          {step === 4 ? "Start again" : "Complete next step"}
        </button>
      </div>
    </DemoFrame>
  );
}

/** Example and adapters: Copyright (c) 2026 NikroZorkin. MIT; licenses/elements.txt. */
import type { ReactNode } from "react";

/** Layout for this example only. The component itself has no catalog dependency. */
export function DemoFrame({
  children,
  className = "",
  hint,
}: {
  children: ReactNode;
  className?: string;
  hint?: string;
}) {
  return (
    <div
      className={`relative flex min-h-[420px] w-full flex-col items-center justify-center gap-7 overflow-hidden p-8 ${className}`}
    >
      {children}
      {hint && (
        <p className="text-center text-xs text-muted-foreground" role="status">
          {hint}
        </p>
      )}
    </div>
  );
}

