          tasks={labels.map((label, index) => ({
            id: String(index),
            label,
            status: index < step ? "done" : index === step ? "running" : "pending",
          }))}
        />
        <button className="demo-action mt-7" onClick={() => setStep(step === 4 ? 0 : step + 1)}>
